using System.Globalization;

var text = Console.In.ReadToEnd();
if (text.Length > 0)
{
    var inputLines = text.Replace("\r\n", "\n").Split('\n');
    if (inputLines[^1].Length == 0) inputLines = inputLines[..^1];
    foreach (var line in inputLines)
    {
        if (line.Length == 0) continue;
        Console.WriteLine(Evaluate(line));
    }
}

static string Evaluate(string line)
{
    var tokens = line.Split(' ');
    if (tokens.Length != 3) return "ERR";
    try
    {
        checked
        {
            var left = int.Parse(tokens[0], CultureInfo.InvariantCulture);
            var right = int.Parse(tokens[2], CultureInfo.InvariantCulture);
            return tokens[1] switch
            {
                "+" => (left + right).ToString(CultureInfo.InvariantCulture),
                "-" => (left - right).ToString(CultureInfo.InvariantCulture),
                "*" => (left * right).ToString(CultureInfo.InvariantCulture),
                "/" => (left / right).ToString(CultureInfo.InvariantCulture),
                _ => "ERR"
            };
        }
    }
    catch (DivideByZeroException) { return "ERR"; }
    catch (OverflowException) { return "ERR"; }
    catch (FormatException) { return "ERR"; }
}
